mapper.select:
SELECT RT.id, RT.template_code, RT.template_name, RT.template_type, RT.status, RT.remark, RT.create_by, COALESCE(NULLIF(SUA.nick_name, ''), SUA.user_name) AS create_name, RT.create_time, RT.update_by, COALESCE(NULLIF(SUB.nick_name, ''), SUB.user_name) AS update_name, RT.update_time FROM rpt_template RT LEFT JOIN sys_account SUA ON RT.create_by = SUA.user_name LEFT JOIN sys_account SUB ON RT.update_by = SUB.user_name
AND RT.template_name LIKE #{templateName}
AND RT.template_code LIKE #{templateCode}
AND RT.template_type = #{template.templateType}
AND RT.status = #{template.status}
ORDER BY RT.create_time DESC
